    "sourceType": "PYQ",
    "questionText": "[IOM 2020 PYQ] [Concept Drill 5] Faraday second law of electrolysis states that when same quantity of electricity passes through different electrolytes, the mass deposited is proportional to:",
    "optionA": "Chemical equivalent weight (E = M / valency)",
    "optionB": "Atomic number",
    "optionC": "Electrochemical equivalent squared",
    "optionD": "Density of the electrolyte",
