    "sourceType": "PYQ",
    "questionText": "[IOM 2019 PYQ] [Concept Drill 5] Which reagent cleanly converts a carboxylic acid (R-COOH) into an alkane (R-H) with one less carbon atom?",
    "optionA": "Soda lime (NaOH + CaO) heating (Decarboxylation)",
    "optionB": "LiAlH4 in dry ether",
    "optionC": "Red P + HI",
    "optionD": "PCl5 followed by H2/Pd",
    "correctOptionIndex": 0,
