    "year": "CEE 2023",
    "sourceType": "PYQ",
    "questionText": "[CEE 2023 PYQ] [Concept Drill 6] According to de Broglie hypothesis, what is the wavelength associated with a 0.1 kg ball moving with a speed of 10 m/s? (h = 6.626 x 10^-34 J*s)",
    "optionA": "6.63 x 10^-34 m",
