    "questionText": "[CEE 2022 PYQ] [Concept Drill 7] According to Molecular Orbital Theory (MOT), what is the bond order and magnetic behavior of the oxygen molecule (O2)?",
    "optionA": "Bond order = 2.0 and Paramagnetic (2 unpaired electrons in pi*2px and pi*2py)",
    "optionB": "Bond order = 2.0 and Diamagnetic",
    "optionC": "Bond order = 1.5 and Paramagnetic",
    "optionD": "Bond order = 2.5 and Diamagnetic",
    "correctOptionIndex": 0,
