    "questionText": "[BPKIHS 2020 PYQ] [Concept Drill 8] According to de Broglie hypothesis, what is the wavelength associated with a 0.1 kg ball moving with a speed of 10 m/s? (h = 6.626 x 10^-34 J*s)",
