    "sourceType": "PYQ",
    "questionText": "[IOM 2020 PYQ] [Target Question 11] The phenotypic ratio obtained in a monohybrid cross exhibiting Incomplete Dominance (e.g., flower color in Mirabilis jalapa) is:",
